function calculate(month,day,hour){if(!Number.isInteger(month)||month<1||month>12||!Number.isInteger(day)||day<1||day>30||!Number.isInteger(hour)||hour<0||hour>23)throw new Error('起盘时间无效');const hourIndex=Math.floor((hour+1)%24/2);const m=(month-1)%6,d=(m+day-1)%6,t=(d+hourIndex)%6;return{m,d,t,hourIndex};}
function calendar(date){if(Number.isNaN(date.getTime()))throw new Error('请选择有效的时间');const parts=new Intl.DateTimeFormat('en-US-u-ca-chinese',{timeZone:'Asia/Shanghai',year:'numeric',month:'numeric',day:'numeric'}).formatToParts(date);const get=k=>parts.find(p=>p.type===k)?.value;const monthText=get('month');const month=parseInt(monthText,10),day=Number(get('day'));if(!month||!day)throw new Error('此浏览器暂不支持农历转换，请使用新版浏览器');const solarParts=new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hourCycle:'h23'}).formatToParts(date);const solar=Object.fromEntries(solarParts.map(p=>[p.type,p.value]));const leap=/bis|闰/i.test(monthText);return{month,day,leap,hour:Number(solar.hour),solar:`${solar.year}-${solar.month}-${solar.day} ${solar.hour}:${solar.minute}:${solar.second}`,label:`农历${leap?'闰':''}${month}月${day}日`,year:Number(solar.year)};}
