const classificationStyle=document.createElement('link');classificationStyle.rel='stylesheet';classificationStyle.href='classification.css';document.head.append(classificationStyle);const lostStyle=document.createElement('link');lostStyle.rel='stylesheet';lostStyle.href='lost-reading.css';document.head.append(lostStyle);const topicStyle=document.createElement('link');topicStyle.rel='stylesheet';topicStyle.href='topic-reading.css';document.head.append(topicStyle);const clarifyStyle=document.createElement('link');clarifyStyle.rel='stylesheet';clarifyStyle.href='clarify.css';document.head.append(clarifyStyle);const autoHint=document.createElement('p');autoHint.id='autoHint';autoHint.setAttribute('aria-live','polite');$('category').insertAdjacentElement('afterend',autoHint);const CLARIFY_PROMPTS={work:'目前处于投递、面试、谈薪还是入职阶段？已经收到什么明确反馈？',cooperation:'现在进展到哪一步？上线或签约还缺什么条件？希望何时完成？',relationship:'当前关系状态、最近一次互动，以及你最想确认的具体结果是什么？',finance:'金额、期限、是否已有合同或到账承诺，以及你能承受的最大损失是多少？',study:'考试时间、目前模拟成绩和最薄弱的科目是什么？',health:'症状持续多久、是否加重、是否已经检查或就医？',travel:'出发日期、交通方式、已确认的票务与当前顾虑是什么？',lost:'最后看见物品的时间地点、之后去过哪里、是否有人移动过？',general:'当前进度、最大的卡点、希望完成的时间和不可接受的代价是什么？'};const clarify=document.createElement('div');clarify.id='clarifyBox';clarify.hidden=true;clarify.innerHTML='<label for="details">补充情况 <small>选填，信息越完整，答案越具体</small></label><p id="clarifyPrompt"></p><textarea id="details" maxlength="300" placeholder="写下当前阶段、已有反馈、主要卡点或时间要求"></textarea>';autoHint.insertAdjacentElement('afterend',clarify);function updateAutoHint(){const q=$('question').value.trim(),selected=$('category').value;if(!q){autoHint.textContent=selected==='auto'?'输入问题后会显示识别结果':`已选择：${CATEGORIES[selected][0]}`;clarify.hidden=true;return;}const c=classifyQuestion(q,selected),sub=detectSubtype(q,c.category);autoHint.innerHTML=`已识别：<b>${CATEGORIES[c.category][0]} · ${sub.label}</b><small>${c.reason}</small>`;clarify.hidden=false;$('clarifyPrompt').textContent=CLARIFY_PROMPTS[c.category]||CLARIFY_PROMPTS.general;}
