function finishCast(){if(!pendingRecord)return;clearTimeout(castTimer);castSteps.forEach(clearTimeout);const record=pendingRecord;pendingRecord=null;render(record);history=[record,...history].slice(0,20);persist();renderHistory();$('questionForm').querySelector('.primary').disabled=false;if(window.innerWidth<801)$('result').scrollIntoView({behavior:'smooth',block:'start'});}
function runCasting(record){pendingRecord=record;clearTimeout(castTimer);castSteps.forEach(clearTimeout);castSteps=[];$('empty').hidden=true;$('result').hidden=true;$('casting').hidden=false;$('casting').className='casting-step-1';$('castStatus').textContent='第一步：按农历月份确定月宫';$('resultTag').textContent='正在起盘';$('questionForm').querySelector('.primary').disabled=true;const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;if(reduced){castTimer=setTimeout(finishCast,180);return;}castSteps.push(setTimeout(()=>{$('casting').className='casting-step-2';$('castStatus').textContent='第二步：从月宫数到农历日期';},750));castSteps.push(setTimeout(()=>{$('casting').className='casting-step-3';$('castStatus').textContent='第三步：从日宫数到当前时辰';},1500));castTimer=setTimeout(finishCast,2400);}
function render(record){
const cal=calendar(new Date(record.iso)),p=calculate(cal.month,cal.day,cal.hour),palace=PALACES[p.t],fullQuestion=record.question+(record.details?' '+record.details:''),subtype=detectSubtype(fullQuestion,record.category);
lastRenderContext={record:record,p:p,brief:palace[2]};
$('empty').hidden=true;
$('casting').hidden=true;
$('result').hidden=false;
$('resultTag').textContent=subtype.label+' · '+palace[0];
let caution='';
if(/癌|疾病|病情|怀孕|药|手术|自杀|自伤|死亡|股票|基金|投资|彩票|赌博|起诉|判刑|官司/.test(fullQuestion))caution='<p class="caution">这类问题涉及健康、安全、财务或法律，盘面不能判断实际结果；请以现实证据及相应专业帮助为依据。</p>';
const wheel=`<div class="grand-compass result-size" aria-label="六宫罗盘，当前落宫${palace[0]}"><div class="compass-aura"></div><div class="compass-bezel"></div><div class="time-orbit">${[...BRANCHES].map((x,i)=>`<span style="--i:${i}">${x}</span>`).join('')}</div><div class="palace-orbit">${PALACES.map((x,i)=>`<span class="${i===p.t?'active':''}" style="--i:${i}">${x[0]}<small>${['安定','迟缓','消息','口舌','助力','未定'][i]}</small></span>`).join('')}</div><div class="compass-axis"></div><div class="compass-needle"></div><div class="compass-hub"><b>${palace[0]}</b><small>时宫落定</small></div></div>`;
const trace=`<details class="trace"><summary>查看计算公式与使用约定</summary><code class="formula">月宫 = (${cal.month}−1) mod 6 = ${p.m}<br>日宫 = (${p.m}+${cal.day}−1) mod 6 = ${p.d}<br>时宫 = (${p.d}+${p.hourIndex+1}−1) mod 6 = ${p.t}</code><p>六宫索引依次为 0 大安、1 留连、2 速喜、3 赤口、4 小吉、5 空亡。每一步都把起点计为一。</p><p>以时宫为最终依据；00:00 换日${cal.leap?'；闰月按原月份计算':''}。完整解读在解锁后由服务端下发，不推定他人真实想法，也不替代现实调查。</p></details>`;
$('result').innerHTML=`${wheel}<div class="result-top"><div class="palace">${palace[0]}</div><div><h2>${palace[1]}</h2><p>${escapeHtml(cal.solar)} · 北京时间<br>${cal.label} · ${BRANCHES[p.hourIndex]}时${record.manual?' · 指定时间':''}</p></div></div><p class="asked">所问：${escapeHtml(record.question)}${record.details?`<small>补充：${escapeHtml(record.details)}</small>`:''}</p><p class="overview"><strong>总览：</strong>${palace[2]} 这是对当前处境的观察角度，不是对未来结果的保证。</p>${caution}${trace}`;
}
function renderHistory(){const el=$('historyList');el.replaceChildren();if(!history.length){el.innerHTML='<p class="no-history">还没有问事记录。</p>';return;}history.forEach(record=>{const btn=document.createElement('button');btn.className='history-item';const cal=calendar(new Date(record.iso)),p=calculate(cal.month,cal.day,cal.hour);btn.innerHTML=`<span>${escapeHtml(record.question)}</span><small>${cal.solar.slice(0,16)} · ${PALACES[p.t][0]}</small>`;btn.addEventListener('click',()=>{$('question').value=record.question;$('category').value=record.category;$('counter').textContent=`${record.question.length} / 300`;render(record);$('result').scrollIntoView({behavior:'smooth',block:'nearest'});});el.append(btn);});}
function tick(){try{const cal=calendar(new Date());$('clock').textContent=cal.solar;$('lunarClock').textContent=cal.label+' · '+BRANCHES[calculate(cal.month,cal.day,cal.hour).hourIndex]+'时';if(!$('manualTime').value)$('manualTime').value=cal.solar.slice(0,16).replace(' ','T');}catch(e){$('clock').textContent='时间读取失败';$('error').textContent=e.message;}}
