$('questionForm').addEventListener('submit',e=>{e.preventDefault();$('error').textContent='';const q=$('question').value.trim(),details=$('details').value.trim();if(q.length<2){$('error').textContent='请写下至少两个字的具体问题。';$('question').focus();return;}try{const date=$('manual').checked?new Date($('manualTime').value+':00+08:00'):new Date();const cal=calendar(date);if(cal.year<1901||cal.year>2100)throw new Error('请选择 1901 至 2100 年的时间');const record={question:q,details,category:detect(q+' '+details,$('category').value),iso:date.toISOString(),manual:$('manual').checked};runCasting(record);}catch(err){$('error').textContent=err.message;}});
$('skipCast').addEventListener('click',finishCast);$('clearHistory').addEventListener('click',()=>{pendingRecord=null;clearTimeout(castTimer);castSteps.forEach(clearTimeout);history=[];persist();renderHistory();$('casting').hidden=true;$('result').hidden=true;$('empty').hidden=false;$('resultTag').textContent='等待起盘';$('questionForm').querySelector('.primary').disabled=false;});$('rulesOpen').addEventListener('click',()=>$('rules').showModal());$('rulesClose').addEventListener('click',()=>$('rules').close());updateAutoHint();tick();setInterval(tick,1000);try{renderHistory();if(history.length)render(history[0]);}catch{$('error').textContent='旧记录无法读取，请清空记录后重新起盘。';}if(!storageOkay)$('error').textContent='浏览器存储不可用，本次结果可能无法保存。';
